const input=$json.body??$json;
const s=v=>String(v??"").trim();
const lower=v=>s(v).toLowerCase();
const lifecycle=lower(input.lifecycle_state??input.lifecycle?.state);
const temperature=lower(input.temperature??input.lifecycle?.temperature);
const intent=lower(input.intent??input.seller_intent);
const motivation=lower(input.motivation??input.motivation_type);
const urgency=lower(input.urgency);
const dealState=lower(input.deal_state??input.pipeline_state??input.deal_status);
const underwriting=lower(input.underwriting_status);
const propertyEvidence=Boolean(input.property_id??input.property?.id);
const sellerReply=s(input.seller_reply??input.inbound_message??input.message_text);
const dnc=input.dnc===true||input.dnc_suppressed===true||lifecycle==="suppressed"||intent==="opt_out";
const leadId=s(input.lead_id??input.identity?.lead_id);
const propertyId=s(input.property_id??input.identity?.property_id);
const dealId=s(input.deal_id??input.identity?.deal_id);
const threadId=s(input.thread_id??input.identity?.thread_id);
const requestId=s(input.request_id??input.communication?.request_id);
const auditId=s(input.audit_id??input.communication?.audit_id);
const missing=[];
if(!leadId&&!dealId)missing.push("lead_id_or_deal_id");
if(!requestId&&!auditId)missing.push("request_id_or_audit_id");
let pipelineStage="seller_follow_up", opportunity="monitor", nextAction="continue_follow_up", nextWorkflow="wf-099-seller-follow-up-timing-cadence", priority="normal", score=50, reason="seller remains in active acquisition follow-up";
if(dnc){pipelineStage="suppressed";opportunity="none";nextAction="suppress_outreach";nextWorkflow=null;priority="critical";score=0;reason="DNC/opt-out blocks acquisition outreach";}
else if(["contracted","under_contract","closing"].some(x=>dealState.includes(x))){pipelineStage="transaction";opportunity="active_transaction";nextAction="protect_and_execute_transaction";nextWorkflow="wf-042-closing-coordination";priority="critical";score=98;reason="deal is already in transaction execution";}
else if(dealState.includes("negotiat")||intent==="negotiation"){pipelineStage="negotiation";opportunity="offer_negotiation";nextAction="advance_negotiation";nextWorkflow="wf-080-offer-negotiation-intelligence";priority="critical";score=92;reason="seller and deal signals support active negotiation";}
else if(dealState.includes("offer")||underwriting==="offer_ready"){pipelineStage="offer_preparation";opportunity="offer_ready";nextAction="prepare_or_review_offer";nextWorkflow="wf-035-offer-preparation-seller-review";priority="high";score=88;reason="deal evidence indicates offer preparation is the next acquisition milestone";}
else if(underwriting==="viable"||underwriting==="approved"){pipelineStage="underwriting";opportunity="underwriting_qualified";nextAction="advance_to_offer_preparation";nextWorkflow="wf-035-offer-preparation-seller-review";priority="high";score=85;reason="underwriting supports advancing the acquisition";}
else if(propertyEvidence&&(temperature==="hot"||temperature==="warm")&&(intent==="positive_interest"||intent==="negotiation"||sellerReply||urgency==="high"||motivation)){pipelineStage="opportunity_qualification";opportunity="high_potential";nextAction="run_deal_viability_and_property_analysis";nextWorkflow="wf-069-deal-viability-mao-strategy-gate";priority="high";score=82;reason="seller engagement plus property evidence justify deal-level qualification";}
else if(lifecycle==="reengagement_due"||lifecycle==="nurture"){pipelineStage="nurture";opportunity="developing";nextAction="nurture_and_reengage";nextWorkflow="wf-100-seller-silence-reengagement";priority="normal";score=35;reason="seller is not currently ready for aggressive acquisition advancement";}
const actionId="deal-pipeline-advance:"+((leadId||dealId||threadId||"unknown"))+":"+(requestId||auditId||"event")+":v1";
return[{json:{ok:missing.length===0,action_id:actionId,pipeline:{stage:pipelineStage,opportunity,priority,score,reason},advancement:{next_action:nextAction,next_workflow:nextWorkflow,autonomous_outbound_allowed:!dnc&&["seller_follow_up","opportunity_qualification","offer_preparation","negotiation"].includes(pipelineStage),requires_human_approval:["offer_preparation","negotiation","transaction"].includes(pipelineStage)},evidence:{lifecycle_state:lifecycle||null,temperature:temperature||null,intent:intent||null,motivation:motivation||null,urgency:urgency||null,deal_state:dealState||null,underwriting_status:underwriting||null,property_evidence:propertyEvidence,seller_reply_present:Boolean(sellerReply)},identity:{lead_id:leadId||null,property_id:propertyId||null,deal_id:dealId||null,thread_id:threadId||null},communication:{request_id:requestId||null,audit_id:auditId||null},missing_requirements:missing}}];

const input=$json;
const code=Number(input.statusCode??0);
const ok=code>=200&&code<300;
return[{json:{ok,action_id:input.action_id??null,pipeline:input.pipeline??null,advancement:input.advancement??null,evidence:input.evidence??null,identity:input.identity??null,communication:input.communication??null,crm_state_sync:{status:ok?"updated":"failed",status_code:code}}}];
